'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const B=require('../architecture/strategy-preview-bridge.cjs');
const Rules=require('../kraken-rules.js');
const policy=require('../rules/kraken/eea-pf-xbtusd-20261021.json');
const normal={schemaVersion:1,mode:'classic-demo',profile:'balanced',referencePriceUSD:'80000',firstEntryPriceUSD:'80000',riskFloorUSD:'60000',buyLadderLowerBoundUSD:'60000',cycleFirstEntryGapUSD:'1000',withinCycleReinforcementGapUSD:'8000',maxCycles:5,nominalCycleBudgetUSD:'1000',walletCashUSD:'2000',reportedIsolatedMarginUSD:'200',plannedMarginAddsUSD:'300',protectedCashUSD:'400'};
const normalContext={asOf:'2026-10-25T12:48:00Z',platform:'europa',clientType:'retail'};
const historicContext={...normalContext,asOf:'2026-10-21T00:00:00Z'};
const run=(inp={},ctx=normalContext,rules=policy,riskEngine=null)=>B.run({request:{...normal,...inp},rules,context:ctx,riskEngine});
test('actual V20 Kraken Rules.load metadata is used',()=>assert.equal(run().sourceRulesVersion,Rules.load(policy).version));
test('15 A-E orders 20/30/50 with exact lot truncation',()=>{const x=run();assert.equal(x.orders.length,15);assert.deepEqual(x.orders.slice(0,3).map(o=>o.targetNominalUSD),['200','300','500']);assert.deepEqual(x.orders.slice(0,3).map(o=>o.quantityBTC),['0.0025','0.0041','0.0078']);});
test('never spend beyond allocated nominal per stage',()=>{const x=run();for(const o of x.orders){assert.ok(Number(o.executableNominalUSD)<=Number(o.targetNominalUSD));assert.ok(Number(o.unspentNominalUSD)>=0);assert.equal(Number(o.executableNominalUSD)+Number(o.unspentNominalUSD),Number(o.targetNominalUSD));}});
test('actual Rules.validateOrder marks valid minimum lot and tick on A-E',()=>{const x=run();assert.ok(x.orders.every(o=>o.metadataValid));});
test('one classic last entry flagged at risk floor even if Kraken tick valid',()=>{const x=run();assert.equal(x.orders.filter(o=>o.blocked).length,1);assert.ok(x.orders.at(-1).issues.includes('AT_OR_BELOW_RISK_FLOOR'));});
test('snapshot from Oct 20 is stale Oct 25, guard blocks risk',()=>{const x=run();assert.equal(x.ruleAssessment.scopeReady,false);assert.equal(x.risk.status,'blocked');assert.ok(x.ruleAssessment.reasons.includes('STALE_RULES'));assert.equal(x.risk.reason,'STALE_OR_OUT_OF_SCOPE_KRAKEN_RULES');});
test('historical time permits metadata preview but floor blocks full risk',()=>{const x=run({},historicContext);assert.equal(x.ruleAssessment.scopeReady,true);assert.equal(x.risk.reason,'INVALID_PRICE_OR_LOT_LADDER');});
test('V20 base valid levels and historical-time risk requires real engine presence',()=>{const x=run({mode:'v20-base-illustrative',cycleFirstEntryGapUSD:'240',withinCycleReinforcementGapUSD:'1200'},historicContext);assert.equal(x.risk.status,'not-evaluated');assert.equal(x.risk.reason,'RISK_ENGINE_NOT_PROVIDED');assert.equal(x.orders.at(-1).entryPriceUSD,'76640');});
test('integration contract forwards correct args to V20 risk method and returns estimate labeled synthetic',()=>{let called;const engine={requiredMarginForFloor:(x)=>{called=x;return {requiredTotalMarginUSD:'1500',initialRequiredUSD:'500',maintenanceRequiredUSD:'250'};}};
 const x=run({mode:'v20-base-illustrative',cycleFirstEntryGapUSD:'240',withinCycleReinforcementGapUSD:'1200'},historicContext,policy,engine);
 assert.equal(x.risk.status,'v20-estimate-under-synthetic-all-fills');assert.equal(called.floorUSD,'60000');assert.equal(called.platform,'europa');assert.equal(called.clientType,'retail');assert.equal(called.basisUSD,x.totals.executableNominalUSD);assert.equal(called.quantityBTC,x.totals.executableQuantityBTC);assert.equal(called.rules.version,policy.version);assert.equal(x.risk.officialLiquidation,false);
});
test('unexpected underlying engine error is blocked, not silently accepted',()=>{const engine={requiredMarginForFloor:()=>{throw Object.assign(new Error('maintenance not ready'),{code:'STALE_MAINTENANCE'});}};const x=run({mode:'v20-base-illustrative',cycleFirstEntryGapUSD:'240',withinCycleReinforcementGapUSD:'1200'},historicContext,policy,engine);assert.equal(x.risk.status,'blocked');assert.equal(x.risk.code,'STALE_MAINTENANCE');});
test('stale risk data cannot even call supplied evaluator',()=>{const engine={requiredMarginForFloor:()=>{throw Error('should not execute')}};const x=run({mode:'v20-base-illustrative',cycleFirstEntryGapUSD:'240',withinCycleReinforcementGapUSD:'1200'},normalContext,policy,engine);assert.equal(x.risk.reason,'STALE_OR_OUT_OF_SCOPE_KRAKEN_RULES');});
test('newer wallet cash cannot be treated as transferred isolated margin',()=>{const x=run();assert.equal(x.ladder.funds.reportedIsolatedMarginUSD,'200');assert.equal(x.ladder.funds.plannedMarginAddsUSD,'300');assert.ok(x.warnings.some(w=>w.startsWith('Planned margin increases')));});
test('a below-minimum-lot draft reports order reasons instead of inventing fill',()=>{const x=run({nominalCycleBudgetUSD:'1'});assert.equal(x.orders.length,15);assert.ok(x.orders[0].issues.includes('BELOW_MIN_QUANTITY'));assert.equal(x.orders[0].quantityBTC,'0');});
test('fractional price not Kraken tick is a blocker',()=>{const x=run({mode:'adjustable-preview',cycleFirstEntryGapUSD:'1000.25',withinCycleReinforcementGapUSD:'8000'});assert.ok(x.orders.some(o=>o.issues.includes('INVALID_PRICE_TICK')));});
test('no authority to persist, trade or automatically apply even when risk engine responds',()=>{const x=run();assert.equal(x.canApply,false);assert.equal(x.mayWriteLedger,false);assert.equal(x.maySubmitOrders,false);assert.equal(x.mayCallExchange,false);assert.equal(x.needsUserApproval,true);});
test('no input mutations and outputs recursively frozen',()=>{const initial=structuredClone(normal),a=run();assert.deepEqual(normal,initial);assert.ok(Object.isFrozen(a)&&Object.isFrozen(a.orders)&&Object.isFrozen(a.orders[0])&&Object.isFrozen(a.ruleAssessment));});
test('invalid jurisdiction/platform not treated as valid EEA risk scope',()=>{const x=run({}, {...historicContext,platform:'other'});assert.equal(x.ruleAssessment.scopeReady,false);assert.ok(x.ruleAssessment.reasons.includes('UNCONFIRMED_PLATFORM'));});
test('schema errors hard fail, no silent defaults',()=>{assert.throws(()=>run({referencePriceUSD:'NaN'}));assert.throws(()=>B.run({request:normal,rules:policy,context:null}),/VALIDATION_TIME_REQUIRED/);});
test('API has no write methods',()=>assert.deepEqual(Object.keys(B),['VERSION','run']));
